      ...stocks.where((s) => s['category'] != 'Index').take(10).map((raw) { final s = raw as Map<String, dynamic>; final change = (s['changePct'] as num).toDouble(); return Container(margin: const EdgeInsets.only(bottom: 8), padding: const EdgeInsets.all(13), decoration: BoxDecoration(color: panel, borderRadius: BorderRadius.circular(12), border: Border.all(color: const Color(0xFF202D40))), child: Row(children: [Container(width: 36, height: 36, alignment: Alignment.center, decoration: BoxDecoration(color: const Color(0xFF1B3049), borderRadius: BorderRadius.circular(10)), child: Text((s['symbol'] as String).substring(0, 1), style: const TextStyle(color: blue, fontWeight: FontWeight.bold))), const SizedBox(width: 11), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(s['symbol'] as String, style: const TextStyle(fontWeight: FontWeight.bold)), Text(s['name'] as String, style: const TextStyle(color: Colors.white54, fontSize: 11), overflow: TextOverflow.ellipsis)])), Column(crossAxisAlignment: CrossAxisAlignment.end, children: [Text('₹${(s['price'] as num).toStringAsFixed(2)}', style: const TextStyle(fontWeight: FontWeight.bold)), Text('${change >= 0 ? '+' : ''}${change.toStringAsFixed(2)}%', style: TextStyle(color: change >= 0 ? green : const Color(0xFFFF8F9B), fontSize: 12))])])); }),
    ], const SizedBox(height: 18), const Text('Research and education only. No orders are placed by this app.', textAlign: TextAlign.center, style: TextStyle(color: Colors.white38, fontSize: 11))
